class Solution:
    def countSchedules(self, n: int, k: int, c: int) -> int:
        MOD = 1000000007
        if n <= k:
            return pow(c, n, MOD)
        # f(i) = number of valid schedules of length i.
        # For i > k: f(i) = (c - 1) * (f(i - 1) + ... + f(i - k)),
        # because the last run has length 1..k and the campaign before it must differ.
        # f(1..k) = c^i.  f(n) is found by computing x^(n - 1) modulo the recurrence polynomial.
        d = (c - 1) % MOD
        first = [pow(c, i, MOD) for i in range(1, k + 1)]

        def multiply(a, b):
            prod = [0] * (2 * k - 1)
            for i in range(k):
                if a[i]:
                    for j in range(k):
                        prod[i + j] = (prod[i + j] + a[i] * b[j]) % MOD
            # x^i = d * (x^(i-1) + ... + x^(i-k))
            for i in range(2 * k - 2, k - 1, -1):
                coef = prod[i] * d % MOD
                if coef:
                    for j in range(1, k + 1):
                        prod[i - j] = (prod[i - j] + coef) % MOD
            return prod[:k]

        result = [1] + [0] * (k - 1)
        base = [0] * k
        if k == 1:
            base[0] = d
        else:
            base[1] = 1
        power = n - 1
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, base)
            base = multiply(base, base)
            power //= 2
        return sum(result[i] * first[i] for i in range(k)) % MOD

